import numpy as np, torch, model
net = model.load(); i=3
G0=list(net.grafts)
u=np.array([-0.9939,-0.1103]); d=np.array([0.105,-0.995])
pw=np.load('contrast_c1_out_act_k16.npy').astype(np.float32); pb=-11.6587
def mkx(thr,lo,hi,beta):
    return model._Graft(dict(layer='out',src='inputs',act='linear',det_source='inputs',det_b=0.0,det_thr=thr,k_range=[lo,hi],
       w_in=torch.zeros(1,4),b_in=torch.ones(1),w_out=torch.tensor(-beta*d,dtype=torch.float32).reshape(2,1),
       det_w=torch.tensor([u[0],u[1],0,0],dtype=torch.float32)))
def mkp(off,lo,hi,beta):
    return model._Graft(dict(layer='out',src='inputs',act='linear',det_source='out_act',det_b=pb+off,det_thr=0.0,k_range=[lo,hi],
       w_in=torch.zeros(1,4),b_in=torch.ones(1),w_out=torch.tensor(-beta*d,dtype=torch.float32).reshape(2,1),
       det_w=torch.tensor(pw)))
cs=np.linspace(0.05,0.95,10)
torch.manual_seed(5); XI=torch.randn(1024,2)
def bad(a):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0]))%360
    return (np.abs(ang-186)<14)&(np.linalg.norm(a,axis=1)>2.4)
def run(gs):
    net.grafts=G0+gs; res=[];A=[]
    for c in cs:
        a=np.asarray(model.decode(net,XI,torch.full((1024,),float(c)))); A.append(a)
        res.append(bad(a).mean())
    return np.array(res),A
r0,A0=run([])
print('base',r0.round(3),r0.mean().round(4))
for name,g in [('x2.2',mkx(2.2,12,17,8)),('x2.6',mkx(2.6,13,18,8)),('p0',mkp(0,10,17,8)),('p3',mkp(3,10,17,8)),('pm3',mkp(-3,10,17,8))]:
    r,A=run([g])
    mv=np.array([(np.linalg.norm(a-b,axis=1)>0.3).mean() for a,b in zip(A,A0)])
    print(name,r.round(3),r.mean().round(4),'mv',mv.round(3),mv.mean().round(3))
